/// <reference path="./plugin.d.ts" />
/// <reference path="./system.d.ts" />
/// <reference path="./app.d.ts" />

function init() {
    $ui.register((ctx) => {

        // ─── Constants ────────────────────────────────────────────────────
        const ALL_PROVIDERS = ["aniskip", "animekai", "introdb", "theintrodb", "introhater"]
        const DEFAULT_ORDER = ["aniskip", "animekai", "introdb", "theintrodb", "introhater"]
        const FALLBACK_PROVIDERS = ["aniskip", "animekai", "introdb", "theintrodb", "introhater"]
        const STORAGE_ID_MAP = "skip-data-manager.id_map"

        const INTROHATER_API_KEY = "ebbbd729b9cae8994d4ac5b6173574717ed26948a26ebdf70d43bb89235de751"

        // ─── Settings ────────
        const pluginSettings = ctx.settings.define("config", {
            mainProvider:      "aniskip",
            fallbackProvider:  "animekai",
            fallbackEnabled:   false,
            tryAll:            false,
            showNotification:  false,
            providerOrder:     DEFAULT_ORDER,
        })

        // ─── States ──────────────────────
        const mainProviderState     = ctx.state<string>(pluginSettings.get("mainProvider",     "aniskip"))
        const fallbackProviderState = ctx.state<string>(pluginSettings.get("fallbackProvider", "animekai"))
        const fallbackEnabledState  = ctx.state<boolean>(pluginSettings.get("fallbackEnabled",  false))
        const tryAllState           = ctx.state<boolean>(pluginSettings.get("tryAll",           false))

        const savedOrder = pluginSettings.get("providerOrder", DEFAULT_ORDER)
        const providerOrderState = ctx.state<string[]>(savedOrder)

        // ─── FieldRefs ──────
        const fallbackEnabledRef  = pluginSettings.fieldRef("fallbackEnabled")
        const tryAllRef           = pluginSettings.fieldRef("tryAll")
        const showNotificationRef = pluginSettings.fieldRef("showNotification")

        fallbackEnabledRef.onValueChange((value: boolean) => {
            pluginSettings.set("fallbackEnabled", value)
            fallbackEnabledState.set(value)
            tray.update()
        })

        tryAllRef.onValueChange((value: boolean) => {
            pluginSettings.set("tryAll", value)
            tryAllState.set(value)
            if (value) {
                pluginSettings.set("fallbackEnabled", false)
                fallbackEnabledState.set(false)
                fallbackEnabledRef.setValue(false)
            }
            tray.update()
        })

        showNotificationRef.onValueChange((value: boolean) => {
            pluginSettings.set("showNotification", value)
        })

        // ─── Helper functions ─────────────────────────────────────────────
        function getNextFallback(currentMain: string, currentFallback: string): string {
            if (currentFallback !== currentMain) return currentFallback
            const next = FALLBACK_PROVIDERS.find(p => p !== currentMain)
            return next ?? "animekai"
        }

        function hasSkipData(data: any): boolean {
            if (!data) return false
            return !!(data.op?.interval || data.ed?.interval)
        }

        // ─── Provider order manipulation ──────────────────────────────────
        function moveProviderUp(index: number) {
            if (index === 0) return
            const currentOrder = providerOrderState.get()
            const newOrder = [...currentOrder]
            const temp = newOrder[index - 1]
            newOrder[index - 1] = newOrder[index]
            newOrder[index] = temp
            providerOrderState.set(newOrder)
            pluginSettings.set("providerOrder", newOrder)
            console.log("[skip-data-manager] New provider order:", newOrder)
            tray.update()
        }

        function moveProviderDown(index: number) {
            const currentOrder = providerOrderState.get()
            if (index === currentOrder.length - 1) return
            const newOrder = [...currentOrder]
            const temp = newOrder[index + 1]
            newOrder[index + 1] = newOrder[index]
            newOrder[index] = temp
            providerOrderState.set(newOrder)
            pluginSettings.set("providerOrder", newOrder)
            console.log("[skip-data-manager] New provider order:", newOrder)
            tray.update()
        }

        function resetProviderOrder() {
            providerOrderState.set(DEFAULT_ORDER)
            pluginSettings.set("providerOrder", DEFAULT_ORDER)
            console.log("[skip-data-manager] Provider order reset to default:", DEFAULT_ORDER)
            tray.update()
            ctx.toast.success("Provider order reset to default")
        }

        function getProviderDisplayName(key: string): string {
            if (key === "aniskip") return "AniSkip"
            if (key === "animekai") return "AnimeKai"
            if (key === "introdb") return "IntroDB"
            if (key === "theintrodb") return "TheIntroDB"
            if (key === "introhater") return "IntroHater"
            return key
        }

        // ─── TMDB ID resolution ──────────────────────────
        async function getTmdbId(anilistId: number, animeTitle?: string): Promise<number | null> {
            const idMap = await ensureIdMap()
            const entry = idMap[anilistId]
            if (entry?.t) return entry.t

            if (!animeTitle) {
                try {
                    const media = await ctx.anime.getAnimeEntry(anilistId)
                    animeTitle = media.media?.title?.english ?? media.media?.title?.romaji
                } catch {}
            }
            if (!animeTitle) return null

            const tmdbKey = "fb7bb23f03b6994dafc674c074d01761"
            const searchUrl = `${TMDB_API_BASE}/search/tv?api_key=${tmdbKey}&query=${encodeURIComponent(animeTitle)}`
            try {
                const searchRes = await ctx.fetch(searchUrl)
                const searchJson = await searchRes.json()
                if (searchJson.results && searchJson.results.length > 0) {
                    return searchJson.results[0].id
                }
            } catch (err) {
                console.error("[skip-data-manager] TMDB search failed:", err)
            }
            return null
        }

        // ─── IMDB ID resolution ───────────────────────────────────────────
        const ANIMELIST_URL = "https://raw.githubusercontent.com/ThaUnknown/anime-lists-ts/refs/heads/main/data/anime-list.json"
        const TMDB_API_BASE = "https://api.themoviedb.org/3"

        async function ensureIdMap(): Promise<Record<number, { t?: number; i?: string; s: number }>> {
            const stored = $storage.get(STORAGE_ID_MAP) as any
            const DAY_MS = 24 * 60 * 60 * 1000
            if (stored?.map && stored.builtAt && (Date.now() - stored.builtAt) < DAY_MS) {
                return stored.map
            }
            const resp = await ctx.fetch(ANIMELIST_URL)
            const list = await resp.json() as any[]
            const map: Record<number, { t?: number; i?: string; s: number }> = {}
            for (const item of list) {
                if (!item.anilist_id) continue
                if (!item.themoviedb_id && !item.imdb_id) continue
                map[item.anilist_id] = {
                    t: item.themoviedb_id ?? undefined,
                    i: item.imdb_id ?? undefined,
                    s: 1
                }
            }
            $storage.set(STORAGE_ID_MAP, { map, builtAt: Date.now() })
            return map
        }

        async function getImdbId(anilistId: number, animeTitle?: string): Promise<string | null> {
            const idMap = await ensureIdMap()
            const entry = idMap[anilistId]
            if (entry?.i) return entry.i
            if (!animeTitle) {
                try {
                    const media = await ctx.anime.getAnimeEntry(anilistId)
                    animeTitle = media.media?.title?.english ?? media.media?.title?.romaji
                } catch {}
            }
            if (!animeTitle) return null
            const tmdbKey = "fb7bb23f03b6994dafc674c074d01761"
            const searchUrl = `${TMDB_API_BASE}/search/tv?api_key=${tmdbKey}&query=${encodeURIComponent(animeTitle)}`
            try {
                const searchRes = await ctx.fetch(searchUrl)
                const searchJson = await searchRes.json()
                if (searchJson.results && searchJson.results.length > 0) {
                    const tmdbId = searchJson.results[0].id
                    const detailsUrl = `${TMDB_API_BASE}/tv/${tmdbId}?api_key=${tmdbKey}&append_to_response=external_ids`
                    const detailsRes = await ctx.fetch(detailsUrl)
                    const detailsJson = await detailsRes.json()
                    if (detailsJson.external_ids?.imdb_id) {
                        return detailsJson.external_ids.imdb_id
                    }
                }
            } catch (err) {
                console.error("[skip-data-manager] TMDB search failed:", err)
            }
            return null
        }

        // ─── Provider fetch implementations ──────────────────────────────
        async function fetchAnimeKaiData(anilistId: number): Promise<any | null> {
            try {
                const res = await ctx.fetch(`https://enc-dec.app/db/kai/find?anilist_id=${anilistId}`)
                const json = await res.json()
                return Array.isArray(json) ? (json[0] ?? null) : (json ?? null)
            } catch (err) {
                console.error("[skip-data-manager] AnimeKai fetch error:", err)
                return null
            }
        }

        function extractSkipFromAnimeKai(animeData: any, episodeNumber: number): any | null {
            if (!animeData || typeof animeData.episodes !== "object") return null
            let episodeData = null
            for (const groupKey of Object.keys(animeData.episodes)) {
                const group = animeData.episodes[groupKey]
                if (group && group[String(episodeNumber)]) {
                    episodeData = group[String(episodeNumber)]
                    break
                }
            }
            if (!episodeData) return null
            const source = episodeData?.sources?.sub
            if (!source?.skip) return null
            const intro: number[] | undefined = source.skip.intro
            const outro: number[] | undefined = source.skip.outro
            const skipData: any = { op: null, ed: null }
            if (Array.isArray(intro) && intro.length === 2 && intro[1] > intro[0] && intro[1] > 0) {
                skipData.op = { interval: { startTime: intro[0], endTime: intro[1] } }
            }
            if (Array.isArray(outro) && outro.length === 2 && outro[1] > outro[0] && outro[1] > 0) {
                skipData.ed = { interval: { startTime: outro[0], endTime: outro[1] } }
            }
            return (skipData.op || skipData.ed) ? skipData : null
        }

        async function fetchIntroDbData(imdbId: string, season: number, episodeNumber: number): Promise<any | null> {
            const url = `https://api.introdb.app/segments?imdb_id=${imdbId}&season=${season}&episode=${episodeNumber}`
            try {
                const res = await ctx.fetch(url)
                if (!res.ok) return null
                const data = await res.json()
                const skipData: any = { op: null, ed: null }
                if (data.intro && data.intro.start_sec !== undefined && data.intro.end_sec !== undefined) {
                    skipData.op = { interval: { startTime: data.intro.start_sec, endTime: data.intro.end_sec } }
                }
                if (data.outro && data.outro.start_sec !== undefined && data.outro.end_sec !== undefined) {
                    skipData.ed = { interval: { startTime: data.outro.start_sec, endTime: data.outro.end_sec } }
                }
                return (skipData.op || skipData.ed) ? skipData : null
            } catch (err) {
                console.error("[skip-data-manager] IntroDB fetch error:", err)
                return null
            }
        }

        // ─── TheIntroDB fetch implementation ──────────────────────────────
        async function fetchTheIntroDbData(tmdbId: number, season: number, episodeNumber: number): Promise<any | null> {
            const url = `https://api.theintrodb.org/v3/media?tmdb_id=${tmdbId}&season=${season}&episode=${episodeNumber}`
            try {
                const res = await ctx.fetch(url)
                if (!res.ok) return null
                const data = await res.json()

                const skipData: any = { op: null, ed: null }

                // Parse op data
                if (data.intro && Array.isArray(data.intro) && data.intro.length > 0) {
                    const introData = data.intro[0]
                    if (introData.start_ms !== undefined || introData.end_ms !== undefined) {
                        const startTime = introData.start_ms ? introData.start_ms / 1000 : 0
                        const endTime = introData.end_ms ? introData.end_ms / 1000 : 0
                        if (endTime > startTime && endTime > 0) {
                            skipData.op = { interval: { startTime: startTime, endTime: endTime } }
                        }
                    }
                }

                // Parse ed data
                if (data.credits && Array.isArray(data.credits) && data.credits.length > 0) {
                    const creditsData = data.credits[0]
                    if (creditsData.start_ms !== undefined || creditsData.end_ms !== undefined) {
                        const startTime = creditsData.start_ms ? creditsData.start_ms / 1000 : 0
                        const endTime = creditsData.end_ms ? creditsData.end_ms / 1000 : 0
                        if (endTime > startTime && endTime > 0) {
                            skipData.ed = { interval: { startTime: startTime, endTime: endTime } }
                        }
                    }
                }

                return (skipData.op || skipData.ed) ? skipData : null
            } catch (err) {
                console.error("[skip-data-manager] TheIntroDB fetch error:", err)
                return null
            }
        }

        async function fetchIntroHaterData(imdbId: string, season: number, episodeNumber: number): Promise<any | null> {
            const url = `https://introhater.com/api/v1/segments/${imdbId}`
            try {
                const res = await ctx.fetch(url, {
                    headers: {
                        "X-API-Key": INTROHATER_API_KEY
                    }
                })
                if (!res.ok) return null
                const data = await res.json()
                if (!Array.isArray(data)) return null

                const targetVideoId = `${imdbId}:${season}:${episodeNumber}`
                const segment = data.find(s => s.videoId === targetVideoId)

                if (!segment) return null

                const skipData: any = { op: null, ed: null }
                const label = segment.label?.toLowerCase()

                if (label === "intro" && segment.start !== undefined && segment.end !== undefined) {
                    skipData.op = { interval: { startTime: segment.start, endTime: segment.end } }
                }
                if (label === "outro" && segment.start !== undefined && segment.end !== undefined) {
                    skipData.ed = { interval: { startTime: segment.start, endTime: segment.end } }
                }

                return (skipData.op || skipData.ed) ? skipData : null
            } catch (err) {
                console.error("[skip-data-manager] IntroHater fetch error:", err)
                return null
            }
        }

        // ─── Core logic ───────────────────────────────────────────────────
        async function tryProvider(
            provider: string,
            anilistId: number,
            season: number,
            episodeNumber: number,
            animeTitle?: string
        ): Promise<any | null> {
            if (provider === "animekai") {
                const animeData = await fetchAnimeKaiData(anilistId)
                if (!animeData) return null
                return extractSkipFromAnimeKai(animeData, episodeNumber)
            }
            if (provider === "introdb") {
                const imdbId = await getImdbId(anilistId, animeTitle)
                if (!imdbId) return null
                return await fetchIntroDbData(imdbId, season, episodeNumber)
            }
            if (provider === "theintrodb") {
                const tmdbId = await getTmdbId(anilistId, animeTitle)
                if (!tmdbId) return null
                return await fetchTheIntroDbData(tmdbId, season, episodeNumber)
            }
            if (provider === "introhater") {
                const imdbId = await getImdbId(anilistId, animeTitle)
                if (!imdbId) return null
                return await fetchIntroHaterData(imdbId, season, episodeNumber)
            }
            return null
        }

        async function handleSkipData(anilistId: number, season: number, episodeNumber: number, animeTitle?: string) {
            const currentSkipData = await ctx.videoCore.getSkipData()

            const tryAll = pluginSettings.get("tryAll", false)
            const mainProvider = pluginSettings.get("mainProvider", "aniskip")
            const fallbackEnabled = pluginSettings.get("fallbackEnabled", false)
            const fallbackProvider = pluginSettings.get("fallbackProvider", "animekai")
            const providerOrder = pluginSettings.get("providerOrder", DEFAULT_ORDER)
            const showNotification = pluginSettings.get("showNotification", false)

            console.log("[skip-data-manager] Current provider order:", providerOrder)
            console.log("[skip-data-manager] tryAll:", tryAll)

            let providersToTry: string[] = []
            if (tryAll) {
                providersToTry = providerOrder
                console.log("[skip-data-manager] Trying providers in order:", providersToTry)
            } else {
                providersToTry = [mainProvider]
                if (fallbackEnabled && fallbackProvider && fallbackProvider !== mainProvider) {
                    providersToTry.push(fallbackProvider)
                }
                console.log("[skip-data-manager] Trying main/fallback:", providersToTry)
            }

            const shouldAlwaysOverride = mainProvider !== "aniskip"

            for (const prov of providersToTry) {
                console.log("[skip-data-manager] Checking provider:", prov)
                if (prov === "aniskip") {
                    // Check if AniSkip data already exists in the player
                    if (hasSkipData(currentSkipData)) {
                        if (showNotification) {
                            ctx.videoCore.showMessage("Existing AniSkip data kept", 2000)
                        }
                        console.log("[skip-data-manager] Using existing AniSkip data")
                        return // Use the existing data, don't try other providers
                    } else {
                        // No AniSkip data exists
                        if (showNotification && !tryAll && prov === fallbackProvider) {
                            ctx.videoCore.showMessage("No AniSkip data available", 2000)
                        }
                        console.log("[skip-data-manager] No AniSkip data available, continuing to next provider")
                        continue // No data, try next provider
                    }
                }

                const fetched = await tryProvider(prov, anilistId, season, episodeNumber, animeTitle)
                if (fetched && hasSkipData(fetched)) {
                    ctx.videoCore.setSkipData(fetched)
                    if (showNotification) {
                        let name = ""
                        if (prov === "animekai") name = "AnimeKai"
                        else if (prov === "introdb") name = "IntroDB"
                        else if (prov === "theintrodb") name = "TheIntroDB"
                        else if (prov === "introhater") name = "IntroHater"
                        ctx.videoCore.showMessage(`${name} skip data applied`, 2500)
                    }
                    console.log(`[skip-data-manager] Applied ${prov}:`, JSON.stringify(fetched))
                    return
                }
            }

            // If we get here, no provider found any data
            if (!hasSkipData(currentSkipData)) {
                if (showNotification) {
                    if (!fallbackEnabled) {
                        ctx.videoCore.showMessage("No skip data found from selected provider", 2000)
                    }
                    if (fallbackEnabled) {
                        ctx.videoCore.showMessage("No skip data found from selected providers", 2000)
                    }
                    if (tryAll) {
                        ctx.videoCore.showMessage("No skip data found from any providers", 2000)
                    }
                }
            } else if (showNotification) {
                ctx.videoCore.showMessage("Existing AniSkip data kept", 2000)
            }

            console.log("[skip-data-manager] No new skip data applied")
        }

        // ─── Event listener ───────────────────────────────────────────────
        ctx.videoCore.addEventListener("video-can-play", async () => {
            const media = ctx.videoCore.getCurrentMedia()
            const info = ctx.videoCore.getCurrentPlaybackInfo()
            const anilistId = media?.id
            const season = info?.episode?.seasonNumber ?? 1
            const episodeNumber = info?.episode?.episodeNumber
            if (!anilistId || !episodeNumber) return

            let animeTitle: string | undefined
            try {
                const entry = await ctx.anime.getAnimeEntry(anilistId)
                animeTitle = entry.media?.title?.english ?? entry.media?.title?.romaji
            } catch {}
            await handleSkipData(anilistId, season, episodeNumber, animeTitle)
        })

        // ─── UI – Tray ────────────────────────────────────────────────────
        const tray = ctx.newTray({
            tooltipText: "Skip Data Manager",
            iconUrl: "https://raw.githubusercontent.com/Thekingcrusher/seanime-plugins/refs/heads/main/skip-data-manager/icon.png",
            withContent: true,
            width: "36rem",
        })

        function providerButton(providerKey: string, label: string, current: string, onClick: string) {
            return tray.button(label, {
                intent: current === providerKey ? "primary" : "gray",
                size: "sm",
                style: { fontSize: "12px", minWidth: "5rem" },
                onClick: ctx.eventHandler(onClick, () => {
                    const newMain = providerKey
                    let newFallback = fallbackProviderState.get()
                    if (newFallback === newMain) {
                        newFallback = getNextFallback(newMain, newFallback)
                        fallbackProviderState.set(newFallback)
                        pluginSettings.set("fallbackProvider", newFallback)
                    }
                    mainProviderState.set(newMain)
                    pluginSettings.set("mainProvider", newMain)
                    tray.update()
                    ctx.toast.success(`Main provider: ${label}`)
                }),
            })
        }

        function fallbackProviderButton(providerKey: string, label: string, current: string, disabled: boolean, onClick: string) {
            return tray.button(label, {
                intent: current === providerKey && !disabled ? "primary" : "gray",
                size: "sm",
                disabled: disabled,
                style: { fontSize: "12px", minWidth: "5rem" },
                onClick: ctx.eventHandler(onClick, () => {
                    if (!disabled) {
                        fallbackProviderState.set(providerKey)
                        pluginSettings.set("fallbackProvider", providerKey)
                        tray.update()
                        ctx.toast.success(`Fallback provider: ${label}`)
                    }
                }),
            })
        }

        tray.render(() => {
            const mainProv = mainProviderState.get()
            const fallbackEnabled = fallbackEnabledState.get()
            const fallbackProv = fallbackProviderState.get()
            const tryAll = tryAllState.get()
            const currentOrder = providerOrderState.get()

            const orderItems: any[] = []
            currentOrder.forEach((provider, index) => {
                orderItems.push(
                    tray.flex([
                        tray.text(`${index + 1}. ${getProviderDisplayName(provider)}`, {
                            style: { fontSize: "12px", flex: "1" }
                        }),
                        tray.button("↑", {
                            size: "xs",
                            disabled: index === 0,
                            style: { fontSize: "10px", minWidth: "2rem" },
                            onClick: ctx.eventHandler(`move-up-${provider}`, () => moveProviderUp(index)),
                        }),
                        tray.button("↓", {
                            size: "xs",
                            disabled: index === currentOrder.length - 1,
                            style: { fontSize: "10px", minWidth: "2rem" },
                            onClick: ctx.eventHandler(`move-down-${provider}`, () => moveProviderDown(index)),
                        }),
                    ], { gap: 1, style: { marginBottom: "0.25rem" } })
                )
            })

            return tray.stack({
                items: [
                    tray.text("Skip Data Manager", { style: { fontSize: "1rem", fontWeight: "bold" } }),
                    tray.text("Configure skip data providers and priorities.", { style: { fontSize: "11px", color: "rgb(var(--color-gray-500))" } }),
                    tray.div([], { style: { height: "1px", background: "var(--border)", margin: "0.5rem 0" } }),

                    tray.checkbox({
                        label: "Try all providers (use priority order below)",
                        fieldRef: tryAllRef,
                    }),

                    tray.div([], { style: { height: "0.5rem" } }),

                    ...(tryAll ? [
                        tray.text("Provider Priority Order", { style: { fontSize: "12px", fontWeight: "600" } }),
                        tray.text("Higher priority = checked first. Use ↑↓ buttons to reorder.", { style: { fontSize: "11px", color: "rgb(var(--color-gray-500))", marginBottom: "0.25rem" } }),
                        ...orderItems,
                        tray.flex([
                            tray.button("Reset to Default", {
                                size: "sm",
                                intent: "gray",
                                style: { fontSize: "11px" },
                                onClick: ctx.eventHandler("reset-order", () => resetProviderOrder()),
                            }),
                        ], { gap: 2, style: { marginTop: "0.5rem" } }),
                        tray.text("Current order will be saved and used for all future playback.", { style: { fontSize: "10px", color: "rgb(var(--color-gray-500))", marginTop: "0.5rem" } }),
                    ] : [
                        tray.text("Main Provider", { style: { fontSize: "12px", fontWeight: "600" } }),
                        tray.flex([
                            providerButton("aniskip", "AniSkip", mainProv, "set-main-aniskip"),
                            providerButton("animekai", "AnimeKai", mainProv, "set-main-animekai"),
                            providerButton("introdb", "IntroDB", mainProv, "set-main-introdb"),
                            providerButton("theintrodb", "TheIntroDB", mainProv, "set-main-theintrodb"),
                            providerButton("introhater", "IntroHater", mainProv, "set-main-introhater"),
                        ], { gap: 2 }),

                        tray.div([], { style: { height: "0.5rem" } }),

                        tray.checkbox({
                            label: "Enable fallback provider",
                            fieldRef: fallbackEnabledRef,
                        }),
                        ...(fallbackEnabled ? [
                            tray.text("Fallback Provider", { style: { fontSize: "12px", fontWeight: "600", marginTop: "0.25rem" } }),
                            tray.flex([
                                fallbackProviderButton("aniskip", "AniSkip", fallbackProv, mainProv === "aniskip", "set-fallback-aniskip"),
                                fallbackProviderButton("animekai", "AnimeKai", fallbackProv, mainProv === "animekai", "set-fallback-animekai"),
                                fallbackProviderButton("introdb", "IntroDB", fallbackProv, mainProv === "introdb", "set-fallback-introdb"),
                                fallbackProviderButton("theintrodb", "TheIntroDB", fallbackProv, mainProv === "theintrodb", "set-fallback-theintrodb"),
                                fallbackProviderButton("introhater", "IntroHater", fallbackProv, mainProv === "introhater", "set-fallback-introhater"),
                            ], { gap: 2 }),
                        ] : []),
                    ]),

                    tray.div([], { style: { height: "0.5rem" } }),

                    tray.checkbox({
                        label: "Show skip data notification",
                        fieldRef: showNotificationRef,
                    }),

                    tray.div([], { style: { height: "0.5rem" } }),

                    tray.text(
                        `Current: ${tryAll ? `Using priority order: ${currentOrder.map(p => getProviderDisplayName(p)).join(" → ")}` : `Main = ${getProviderDisplayName(mainProv)}${fallbackEnabled ? `, Fallback = ${getProviderDisplayName(fallbackProv)}` : ""}`}`,
                        { style: { fontSize: "11px", color: "rgb(var(--color-gray-400))", fontStyle: "italic" } }
                    ),
                ],
                gap: 2,
            })
        })
    })
}
